// Common Operations on File Descriptor 'fd'
int result;
int old_flags;

// 1. Get File Status Flags (e.g., O_RDWR, O_NONBLOCK)
old_flags = fcntl(fd, F_GETFL);

// 2. Set Status Flags (e.g., Enable Non-Blocking I/O)
if (old_flags != -1) {
    old_flags |= O_NONBLOCK;
    result = fcntl(fd, F_SETFL, old_flags);
}

// 3. Duplicate FD (F_DUPFD_CLOEXEC: >= arg, close on exec)
int new_fd = fcntl(fd, F_DUPFD_CLOEXEC, 100);
// new_fd is the lowest available descriptor >= 100

// 4. Set FD Flags (FD_CLOEXEC: close on exec)
result = fcntl(fd, F_SETFD, FD_CLOEXEC);
// Returns 0 on success, -1 on error (EACCES common)
// Use fcntl64() if required for large file support context.
